<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad,onPullDownRefresh,onShow } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import { qualityApi } from '../../api/quality.api'
import { appConfig } from '@/app/config/env'
import type { GoodFlowerVideoSummary,QualityTask,SelfInspectionLocation } from '../../models/quality'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import SessionTrigger from '@/shared/components/SessionTrigger.vue'
import { sessionStore } from '@/store/session'
import { scanner } from '@/platform/scanner'

type Domain='assigned'|'self'|'video'
type TaskGroup={key:string;location:string;tasks:QualityTask[];quantity:number;allocatedQuantity:number;pending:number;priority:boolean;markers:{return:boolean;exchange:boolean}}
const date=ref(new Date().toISOString().slice(0,10)),domain=ref<Domain>('assigned'),status=ref(-1),subtype=ref('all'),keyword=ref(''),tasks=ref<QualityTask[]>([]),selfLocations=ref<SelfInspectionLocation[]>([]),videos=ref<GoodFlowerVideoSummary>({required:0,completed:0,records:[]}),loading=ref(true),error=ref('')
const sessionPickerVisible=ref(false)
const assigneeUserId=ref<number>(),assigneeName=ref(''),attendanceStatus=ref<number>()
const personnelMode=computed(()=>assigneeUserId.value!==undefined)
const canViewTasks=computed(()=>sessionStore.can('quality.task.view')||(personnelMode.value&&sessionStore.can('inspectionAttendance.view')))
const assignedTasks=computed(()=>tasks.value.filter(item=>item.taskType==='assigned'))
const assignedPending=computed(()=>assignedTasks.value.filter(item=>item.status===0).length),assignedDone=computed(()=>assignedTasks.value.filter(item=>item.status!==0).length)
const selfReturnCount=computed(()=>selfLocations.value.filter(item=>item.markers.return).length),selfExchangeCount=computed(()=>selfLocations.value.filter(item=>item.markers.exchange).length)
const videoProgress=computed(()=>videos.value.required?Math.min(100,Math.round(videos.value.completed/videos.value.required*100)):0)
const statusLabel=computed(()=>status.value===0?'待检查':status.value===1?'已完成':'全部状态')
const subtypeLabel=computed(()=>domain.value==='assigned'?({all:'全部客户',big:'大客户',new:'新客户'}[subtype.value]||'全部客户'):({all:'全部标记',return:'退货',exchange:'换货'}[subtype.value]||'全部标记'))
const groups=computed<TaskGroup[]>(()=>{const source=assignedTasks.value.filter(item=>(status.value<0||(status.value===0?item.status===0:item.status!==0))&&(subtype.value==='all'||item.customerType===subtype.value)).filter(item=>{const term=keyword.value.trim();return !term||item.location.includes(term)||item.receiverPhone.includes(term)});const map=new Map<string,QualityTask[]>();source.forEach(item=>map.set(item.location,[...(map.get(item.location)||[]),item]));return [...map.entries()].map(([location,rows])=>({key:location,location,tasks:rows,quantity:rows.reduce((sum,item)=>sum+item.quantity,0),allocatedQuantity:rows.reduce((sum,item)=>sum+item.allocatedQuantity,0),pending:rows.filter(item=>item.status===0).length,priority:rows.some(item=>item.priority||item.focused),markers:{return:rows.some(item=>item.markers.return),exchange:rows.some(item=>item.markers.exchange)}}))})
const assignedSections=computed(()=>[
  {key:'allocated',title:'已配货',rows:groups.value.filter(item=>item.allocatedQuantity>0),tip:''},
  {key:'unallocated',title:'未配货',rows:groups.value.filter(item=>item.allocatedQuantity===0),tip:'花材整单缺货时，该货位任务无需完成'},
].filter(section=>section.rows.length))
const visibleSelfLocations=computed(()=>selfLocations.value.filter(item=>subtype.value==='all'||item.markers[subtype.value as 'return'|'exchange']).filter(item=>!keyword.value.trim()||item.location.includes(keyword.value.trim())))
async function load(){if(!canViewTasks.value){loading.value=false;return}loading.value=true;error.value='';try{const targetUserId=assigneeUserId.value;const [taskRows,selfRows,videoData]=await Promise.all([qualityApi.getTasks(date.value,undefined,targetUserId),qualityApi.getSelfInspectionLocations(date.value,targetUserId),qualityApi.getGoodFlowerVideos(date.value,targetUserId)]);tasks.value=taskRows;selfLocations.value=selfRows;videos.value=videoData}catch(e){error.value=e instanceof Error?e.message:'质检任务加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function switchDomain(value:Domain){domain.value=value;status.value=-1;subtype.value='all';keyword.value=''}
function chooseStatus(){const values=[-1,0,1],labels=['全部状态','待检查','已完成'];uni.showActionSheet({itemList:labels,success:({tapIndex})=>status.value=values[tapIndex]})}
function chooseSubtype(){const assigned=domain.value==='assigned',values=assigned?['all','big','new']:['all','return','exchange'],labels=assigned?['全部客户','大客户','新客户']:['全部标记','退货','换货'];uni.showActionSheet({itemList:labels,success:({tapIndex})=>subtype.value=values[tapIndex]})}
function openDistributionShelf(item:SelfInspectionLocation){const shelf=item.location.replace(/^#/,'').replace(/段$/,'');uni.navigateTo({url:`/features/distribution/pages/shelf-detail/index?date=${encodeURIComponent(date.value)}&shelf=${encodeURIComponent(shelf)}`})}
function openTask(group:TaskGroup){const pending=group.tasks.find(item=>item.status===0)||group.tasks[0];if(pending)uni.navigateTo({url:`/features/quality/pages/task-detail/index?id=${pending.id}`})}
async function scanVideo(){try{const result=await scanner.scan({scanType:['qrCode']});uni.navigateTo({url:`/features/quality/pages/video-submit/index?date=${encodeURIComponent(date.value)}&content=${encodeURIComponent(result.value)}`})}catch(e){if(e instanceof Error&&!/cancel/i.test(e.message))uni.showToast({title:e.message||'未完成扫码',icon:'none'})}}
function mediaUrl(value:string){return value.startsWith('http')?value:`${appConfig.apiBaseUrl}${value}`}
function recordTime(value:string){const time=new Date(value);if(Number.isNaN(time.getTime()))return value;return `${String(time.getHours()).padStart(2,'0')}:${String(time.getMinutes()).padStart(2,'0')}`}
function openVideo(recordId:number){const row=videos.value.records.find(item=>item.id===recordId);if(row)uni.showActionSheet({itemList:['播放视频'],success:()=>uni.previewMedia({sources:[{url:row.videoUrl.startsWith('http')?row.videoUrl:`${appConfig.apiBaseUrl}${row.videoUrl}`,type:'video'}]})})}
async function changeDate(value:string){date.value=value;await load()}
onLoad(async query=>{if(query?.date)date.value=String(query.date);if(query?.assigneeUserId){const id=Number(query.assigneeUserId);if(Number.isInteger(id)&&id>0)assigneeUserId.value=id;assigneeName.value=decodeURIComponent(String(query.assigneeName||''));attendanceStatus.value=Number(query.attendanceStatus)}await load()});onShow(()=>{if(!loading.value)load()});onPullDownRefresh(load)
</script>

<template><view class="page">
  <WareState v-if="!canViewTasks" type="forbidden" title="暂无质检任务权限" description="请联系管理员开通 quality.task.view 能力"/>
  <template v-else>
  <view class="top"><SessionTrigger :value="date" @click="sessionPickerVisible=true"/><view class="head-badge">质检任务</view></view>
  <view v-if="personnelMode" class="inspector-card"><view><strong>{{assigneeName||'质检人员'}}</strong><text>账号 ID：{{assigneeUserId}}</text></view><text :class="attendanceStatus===1?'working':'resting'">{{attendanceStatus===1?'出勤':'休息'}}</text></view>
  <view class="overview">
    <view @click="switchDomain('assigned')"><text>派发任务</text><strong>{{assignedPending}}<small>/{{assignedTasks.length}}</small></strong><span>完成 {{assignedDone}}</span></view>
    <view @click="switchDomain('self')"><text>自行货位检查</text><strong>{{selfLocations.length}}<small>个货位</small></strong><span>退货 {{selfReturnCount}} · 换货 {{selfExchangeCount}}</span></view>
    <view @click="switchDomain('video')"><text>拍摄好花视频</text><strong>{{videos.completed}}<small>/{{videos.required}}</small></strong><span>今日进度</span></view>
  </view>
  <view class="domain-tabs"><view :class="{active:domain==='assigned'}" @click="switchDomain('assigned')">派发任务</view><view :class="{active:domain==='self'}" @click="switchDomain('self')">自行货位检查</view><view :class="{active:domain==='video'}" @click="switchDomain('video')">拍摄好花视频</view></view>
  <WareState v-if="loading" type="loading" title="正在加载质检任务"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/>
  <template v-else-if="domain==='video'">
    <button v-if="!personnelMode" class="scan-button" @click="scanVideo"><text class="scan-icon"/>扫码拍摄</button><text v-if="!personnelMode" class="scan-tip">扫描花材二维码，确认对象后拍摄视频</text>
    <view class="progress-card"><view><strong>今日完成 <text>{{videos.completed}}/{{videos.required}}</text></strong><span>{{videoProgress}}%</span></view><view class="progress"><text :style="{width:`${videoProgress}%`}"/></view><small v-if="videos.required===0">本场次暂未配置拍摄指标，提交记录仍会正常保留</small></view>
    <view class="list-head video-head"><strong>拍摄记录</strong><text>{{videos.records.length}}条记录</text></view>
    <WareState v-if="!videos.records.length" type="empty" title="暂无拍摄记录" description="扫描花材二维码后开始拍摄"/>
    <view v-else class="video-list"><view v-for="record in videos.records" :key="record.id" class="video-row" @click="openVideo(record.id)"><video class="video-thumb" :src="mediaUrl(record.videoUrl)" :controls="false" :show-center-play-btn="true" :show-play-btn="false" :enable-progress-gesture="false" @click.stop="openVideo(record.id)"/><view class="video-info"><view><strong>{{record.location}}　{{record.flowerName}} · {{record.grade}}</strong><span>已提交</span></view><text>{{record.supplierName}}</text><small>{{recordTime(record.updatedAt)}}</small></view><text class="arrow"/></view><view class="list-end"><text/>没有更多了<text/></view></view>
  </template>
  <template v-else>
    <view class="compact-filter">
      <view class="search"><text class="search-icon"/><input v-model="keyword" :placeholder="domain==='assigned'?'搜索货位或客户手机号':'搜索货位'"/><text v-if="keyword" class="clear" @click="keyword=''">×</text></view>
      <view class="filter-trigger" :class="{selected:subtype!=='all'}" @click="chooseSubtype"><text>{{subtypeLabel}}</text><i/></view>
      <view v-if="domain==='assigned'" class="filter-trigger" :class="{selected:status!==-1}" @click="chooseStatus"><text>{{statusLabel}}</text><i/></view>
    </view>
    <template v-if="domain==='assigned'">
      <WareState v-if="!groups.length" type="empty" title="暂无符合条件的质检任务" description="可以切换客户类型、状态或搜索条件"/>
      <view v-else class="assigned-sections"><view v-for="section in assignedSections" :key="section.key" class="assigned-section"><view class="section-head"><view><i/><strong>{{section.title}}</strong><text>({{section.rows.length}})</text></view><span v-if="section.tip">{{section.tip}}</span></view><view class="list"><view v-for="group in section.rows" :key="group.key" class="task assigned-task" @click="openTask(group)"><view class="task-top"><strong>{{group.location}}</strong><view class="marks"><text v-if="group.priority" class="priority">重点</text><text :class="group.pending?'pending':'done'">{{group.pending?'待质检':'已完成'}}</text></view></view><view class="task-progress"><text>涉及扎数：{{group.quantity}}</text><text>已配：{{group.allocatedQuantity}}</text></view><view class="task-bottom"><text>{{group.tasks.length}}项花材</text><text>{{group.pending?`待检查 ${group.pending}/${group.tasks.length}`:'查看结果'}}</text></view><view class="card-chevron"/></view></view></view></view>
    </template>
    <template v-else>
      <view class="self-note">按标记计任务，同一货位可同时包含退货、换货</view>
      <view class="list-head"><strong>标记货位</strong><text>{{visibleSelfLocations.length}}个货位</text></view>
      <WareState v-if="!visibleSelfLocations.length" type="empty" title="暂无对应标记" description="花材质检产生退货或换货标记后，会在这里自动汇总"/>
      <view v-else class="self-list"><view v-for="item in visibleSelfLocations" :key="item.location" class="self-task" @click="openDistributionShelf(item)"><view class="task-top"><strong>{{item.location}}</strong><view class="marks"><text v-if="item.markers.return" class="return">退货</text><text v-if="item.markers.exchange" class="exchange">换货</text></view></view><text class="self-flowers">{{item.flowerSummary}}</text><view class="self-meta"><text>{{item.flowerCount}}项花材</text><text>{{item.markedUnitCount}}扎已标记</text></view><small>{{item.supplierSummary}}</small><view class="card-chevron"/></view></view>
    </template>
  </template>
  <SessionDatePicker v-model="date" v-model:visible="sessionPickerVisible" @confirm="changeDate"/>
  </template>
</view></template>

