</style>
<style scoped>.top{display:flex;align-items:center;justify-content:space-between;gap:20rpx}.top :deep(.session-trigger){flex:none}.head-badge{padding:9rpx 15rpx;border-radius:999rpx;background:var(--wms-surface-soft);color:var(--wms-primary-700);font-size:22rpx;font-weight:700;white-space:nowrap}</style>
<style scoped>.inspector-card{display:flex;align-items:center;justify-content:space-between;margin:10rpx 0 16rpx;padding:20rpx 22rpx;border-radius:14rpx;background:#fff}.inspector-card strong,.inspector-card view>text{display:block}.inspector-card strong{font-size:27rpx}.inspector-card view>text{margin-top:5rpx;color:var(--wms-text-secondary);font-size:19rpx}.inspector-card>text{padding:6rpx 11rpx;border-radius:5rpx;font-size:18rpx}.inspector-card .working{background:var(--wms-surface-soft);color:var(--wms-success)}.inspector-card .resting{background:#fde8e8;color:var(--wms-danger)}</style>
